"""Dependency-free static, privacy-safe public dashboard builder."""
import json, html, sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import projection
D=json.loads(Path('data/evidence.json').read_text())
e=html.escape
nav=[('index','Executive summary')]+[(p['id'],p['title']) for p in D['pages']]+[('sources','Sources & methodology'),('dashboard/index','Category dashboard')]
def shell(id,title,content):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Privacy-safe, evidence-linked Los Angeles net lease property research. Unknown financial values are withheld."><title>{e(title)} · Asset A · Net-lease decision file</title><link rel="stylesheet" href="assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="mark">A.</span> ASSET A<span class="brand-sub">NET-LEASE DECISION FILE</span></a><div class="nav-label">DECISION WORKSPACE</div><nav>{''.join(f'<a {"aria-current=page" if key==id else ""} href="{key}.html"><span>{str(i+1).zfill(2)}</span>{e(label)}</a>' for i,(key,label) in enumerate(nav))}</nav><div class="privacy"><span>◈</span><b>Privacy by design</b><p>Asset A · anonymized<br>No owner or parcel identifiers</p></div></aside><div class="workspace"><header><span>RESEARCH / LOS ANGELES</span><span class="stamp">● &nbsp; Evidence snapshot · 10 Nov 2026</span></header><main id="main"><section class="callout"><b>Evidence boundary.</b> Asset A is anonymized: no address, parcel, owner or executed lease is published. No valuation, cap rate or sale price is asserted. Companion research layers are kept in the repository but withheld from this site, including the <code>/advisory/</code> projections. <a href="review.html">Flagged for Review</a>.</section>{content}</main><footer>Independent decision-support research. Not an appraisal, legal opinion or personalized financial advice.<br>Static evidence snapshot · No tracking, forms, third-party assets or private documents · <a href="sources.html">Methodology &amp; limitations</a></footer></div></body></html>'''
def table(p):
    heads=p['columns']+['Evidence','Official source']
    out='<div class="table-wrap"><table><caption>'+e(p['title'])+' · evidence register</caption><thead><tr>'+''.join('<th scope="col">'+e(c)+'</th>' for c in heads)+'</tr></thead><tbody>'
    for r in p['rows']:
        s=D['sources'][r['source']]; status=r['status']; cls='verified' if status=='Verified' else 'analysis' if status=='Analysis' else 'unknown'
        out+='<tr>'+''.join('<td'+(' class="empty" aria-label="Unverified value; intentionally blank"' if c=='' else '')+'>'+e(c)+'</td>' for c in r['cells'])+f'<td><span class="badge {cls}">{e(status)}</span></td><td><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["label"])} ↗</a></td></tr>'
    return out+'</tbody></table></div>'
def _pct(x, dp=2):
    return f"{x*100:+.{dp}f}%"

def _num(x, dp=2):
    return f"{x:.{dp}f}"

def projection_section():
    """Deterministic break-even tables. Analysis only: no property value is asserted."""
    M = projection.compute()
    h = M['horizon_years']
    be = ''.join(
        '<tr><th scope="row">' + _num(r['discount']*100, 2) + '% required return</th>' +
        ''.join('<td>' + ('not reachable' if v['growth'] is None else _pct(v['growth']) + '/yr') + '</td>' for v in r['values']) +
        '<td><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">DGS10 ↗</a></td></tr>' for r in M['break_even'])
    be_head = ''.join('<th scope="col">exit cap ' + _num(c*100, 1) + '%</th>' for c in projection.CAP_RATES)
    grid = ''
    for r in M['ratio_grid']:
        cells = ''
        for v in r['values']:
            lead = ' hold ahead' if v['ratio'] >= 1 else ''
            cells += '<td' + (' class="hit"' if v['ratio'] >= 1 else '') + '>' + _num(v['ratio'], 2) + lead + '</td>'
        grid += ('<tr><th scope="row">exit cap ' + _num(r['cap_exit']*100, 1) + '% · rent ' + _pct(r['growth'], 1) + '/yr</th>' + cells + '<td><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">DGS10 ↗</a></td>' + '</tr>')
    grid_head = ''.join('<th scope="col">' + _num(d*100, 2) + '% return</th>' for d in projection.DISCOUNT_RATES)
    vac = ''.join('<tr><th scope="row">exit cap ' + _num(r['cap_exit']*100, 1) + '%</th><td>' + _num(r['with_rent'], 2) +
                  '</td><td>' + _num(r['with_vacancy'], 2) + '</td><td>' + _num(r['loss_pct']*100, 1) + '%</td><td><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">DGS10 ↗</a></td></tr>'
                  for r in M['vacancy']['rows'])
    return f"""<div class="section-heading"><h2>Break-even calculation</h2><span>Analysis · disclosed arithmetic, not a forecast</span></div>
<section class="callout"><h2>What the public record can answer, and what it cannot</h2>
<p><b>Cannot:</b> a sale price, a market rent, a cap rate, or the chance the tenant renews. No government agency publishes a cap rate for this asset, the tenant's lease is private, and the owner has not supplied rent, basis or debt. Anything presented as a dollar forecast would therefore be invented.</p>
<p><b>Can:</b> the one comparison the assumed inputs decide. Restate the question in units that do not need the missing facts: with a required return, an exit cap rate and a rent-growth rate, is {h} more years of rent plus a sale at the end of them worth more than selling today at today's cap rate? Every money figure below is a multiple of <b>one year of current contractual base rent</b>, which cancels out of the ranking.</p>
<p><b>Disclosed assumptions.</b> Horizon {h} years (to 2035, the latest expiry you reported); rent paid in arrears and growing annually; exit at the end of year {h} at the stated cap applied to then-current rent; base cap rate today {_num(M['base_cap_now']*100,1)}% for every comparison; discount-rate floor {_num(M['treasury_anchor']*100,2)}% from the 10-year Treasury on {M['treasury_anchor_date']} (Federal Reserve H.15 via FRED DGS10), with higher required returns swept because the owner's is private.</p>
<p><b>Excluded and disclosed:</b> transaction costs, the 0.45% city base transfer tax, Measure ULA at 4%/5.5%, federal and California income tax, depreciation recapture at up to 25%, capital expenditure, insurance repricing, financing, and tenant default before expiry. Each is a verified rule or a private fact; apply it on top of these multiples.</p></section>
<div class="table-wrap"><table><caption>Break-even rent growth · rent growth needed for holding to equal selling today (base cap rate {_num(M['base_cap_now']*100,1)}%)</caption><thead><tr><th scope="col">Required return</th>{be_head}<th scope="col"><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">Rate anchor (DGS10) ↗</a></th></tr></thead><tbody>{be}</tbody></table></div>
<p class="lede" style="font-size:14px">Read down a column: the more return you require, the more rent growth the hold has to deliver merely to break even. At a 6.0% exit cap, a 4.86% required return needs about {_pct(projection.break_even_growth(projection.BASE_CAP_NOW, 0.06, projection.TREASURY_ANCHOR))} a year of rent growth; at a 7.0% required return the same asset has to grow rent at about {_pct(projection.break_even_growth(projection.BASE_CAP_NOW, 0.06, 0.07))} a year. Nothing in the published regional data establishes either rate, which is why the answer turns on your required return and on the exit cap, not on county demographics.</p>
<div class="table-wrap"><table><caption>Present value of holding ÷ proceeds of selling today · above 1.00 means holding is ahead before costs and tax</caption><thead><tr><th scope="col">Exit cap · rent growth</th>{grid_head}<th scope="col"><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">Rate anchor (DGS10) ↗</a></th></tr></thead><tbody>{grid}</tbody></table></div>
<div class="table-wrap"><table><caption>Stress: {M['vacancy']['vacancy_months']}-month void at expiry, re-let at {int(M['vacancy']['release_rent_factor']*100)}% of prior rent, at a 4.86% required return and 1.0%/yr rent growth</caption><thead><tr><th scope="col">Exit cap</th><th scope="col">Multiple with rent to expiry</th><th scope="col">Multiple with the void</th><th scope="col">Value lost</th><th scope="col"><a href="https://fred.stlouisfed.org/series/DGS10" target="_blank" rel="noopener noreferrer">Rate anchor (DGS10) ↗</a></th></tr></thead><tbody>{vac}</tbody></table></div>
<p class="lede" style="font-size:14px">The stress column is the asymmetry that decides the risk balance: an 18-month void at expiry costs roughly a tenth of the holding value, and it arrives at the moment the lease gives you no protection. Selling while the income is contractual converts an unknown renewal into a priced outcome, which is why the recommendation runs the sale track and the renewal track at the same time rather than waiting for the option clock.</p>
<div class="legend"><span class="badge analysis">Analysis</span> Every figure above is computed by <code>scripts/projection.py</code> from the disclosed assumptions; none of it is a property valuation, a forecast or a probability.</div>"""


for p in D['pages']:
    intro=f'<div class="eyebrow">{e(p["kicker"])}</div><h1>{e(p["title"])}</h1><p class="lede">{e(p["description"])}</p><div class="legend"><span class="badge verified">Verified</span> Source-matched observation <span class="badge analysis">Analysis</span> Conditional interpretation <span class="badge unknown">Unverified</span> Missing evidence</div>'
    Path(p['id']+'.html').write_text(shell(p['id'],p['title'],intro+table(p)+(projection_section() if p['id']=='model' else '')))
content='''<div class="eyebrow">ASSET A · CENTRAL LOS ANGELES · NET-LEASE DECISION FILE</div><h1>Protect the income.<br><span>Own the exit.</span></h1><p class="lede">A source-linked decision file for an anonymized Jack in the Box net-leased restaurant property reported to expire between 2030 and 2035. Every published figure is traceable to a government or issuer page; everything that could not be verified is left blank and listed on the review page.</p><div class="hero-note"><span class="badge analysis">CONDITIONAL RECOMMENDATION · ANALYST JUDGEMENT, NOT A VALUATION</span><h2>Run both tracks now: market the asset for sale, and demand renewal terms in writing.</h2><p>Start a confidential sale process 24–36 months before the earliest expiry, in parallel with a written renewal request. Convert to whichever result the documents support: a verified after-tax sale, or an enforceable extension of ten years or more at market rent with acceptable credit. What is not defensible is letting a 2030–2035 option clock run out on regional averages alone.</p><a class="button" href="decisions.html">Decision pathways &amp; triggers <span>→</span></a><a class="quiet" href="taxes.html">After-tax cost of each route ↗</a></div><section class="split"><div><div class="eyebrow">WHY NOW RATHER THAN AT EXPIRY</div><h2>Every verified trend is flat or negative.</h2><p>City population is 0.8% below its 2020 estimates base and the county is 3.2% below. Metro payrolls grew 0.5% year over year, led by education and health while information fell 5.7%. The tenant reports system same-store sales of −1.1% and is closing 150–200 restaurants, with the remainder tied to franchise-agreement termination dates.</p><p>An expiring lease transfers negotiating leverage to the party that can wait. Marketing while income is contractual, and while the tenant still needs the site, is the lower-risk way to preserve capital.</p></div><div class="callout"><h3>What would change this view</h3><p>A signed extension at market rent backed by acceptable credit; a verified after-tax bid above the hold case; block-level evidence that this trade area is growing; or a change in the owner's liquidity needs.</p><p><b>None of these can be established from the regional data published here.</b> The property's rent, basis, debt and lease are not public records we hold.</p><a href="review.html">Inspect the evidence gaps →</a></div></section><div class="section-heading"><h2>The evidence in three numbers</h2><span>Regional context ≠ property forecast</span></div><div class="cards"><article><div class="eyebrow">DEMAND / LA CITY</div><strong>−0.8%</strong><p>Population change, April 2020 estimates base to July 2025. A demand headwind, not a local sales forecast.</p><a href="https://www.census.gov/quickfacts/losangelescitycalifornia">Census · V2025 ↗</a></article><article><div class="eyebrow">JOBS / LA METRO</div><strong>+0.5%</strong><p>Nonfarm employment, September 2026 versus September 2025, not seasonally adjusted. Growth is thinner than inflation.</p><a href="https://www.bls.gov/regions/west/summary/blssummary_losangeles.pdf">BLS · November 2026 summary ↗</a></article><article><div class="eyebrow">TENANT / CHAIN-WIDE</div><strong>−1.1%</strong><p>System same-store sales, third quarter FY2026. This is not the subject restaurant's performance and not the guarantor's rent coverage.</p><a href="tenant.html">Issuer evidence &amp; lease gaps ↗</a></article></div><div class="section-heading"><h2>Risk balance</h2><span>Business as usual, then the tail</span></div><section class="split"><div><h2 style="font-size:19px">Business as usual</h2><p><b>Income concentration.</b> One tenant, one building, one lease. A vacancy costs the full rent, plus taxes, insurance and re-letting.</p><p><b>Wage and cost pressure.</b> Covered fast-food work pays $20.00/hour under AB 1228, and the state floor is $16.90/hour from 2026. Rent coverage at the store level is unknown.</p><p><b>Rates and exit yields.</b> The 10-year Treasury was 4.86% on 6 November 2026. A higher exit yield lowers price for the same rent.</p><p><b>Taxes.</b> A city sale above $5.4m carries a 4% Measure ULA surcharge on top of the 0.45% city base tax; §1031 defers, and does not eliminate, capital-gain tax.</p></div><div><h2 style="font-size:19px">Tail events that can end the local economy</h2><p><b>Wildfire.</b> In 2025 the Palisades and Eaton fires destroyed 16,264 structures in this county in 24 days. Insurance availability and pricing can change for the whole region afterwards.</p><p><b>Earthquake.</b> USGS models a plausible M7.8 southern San Andreas event at ~1,800 deaths and ~$213bn in losses. Parcel-level ground-failure exposure has not been checked.</p><p><b>Flood, and correlated utility or pandemic disruption.</b> The FEMA map service is the official source; no parcel zone has been assigned.</p><p><b>Tenant failure or accelerated closure.</b> The issuer's own programme closes underperforming units and sells owned real estate. Neither establishes this site's fate, but both remove the assumption that a chain lease is permanent.</p><a href="risk.html">Read the full risk register →</a></div></section><div class="section-heading"><h2>Read by category</h2><span>Twelve pages · every row carries its source</span></div><div class="route-grid"><a href="economy.html"><b>Area fundamentals</b><p>Population, income, payrolls, prices and wages.</p>Read the evidence →</a><a href="demographics.html"><b>Trade area &amp; demographics</b><p>Households, age, poverty and spending capacity.</p>Read the evidence →</a><a href="tenant.html"><b>Tenant &amp; lease</b><p>Issuer results, closures and the missing lease.</p>Read the evidence →</a><a href="risk.html"><b>Risk &amp; resilience</b><p>Business-as-usual and black-swan events.</p>Review downside →</a><a href="place.html"><b>Neighborhood &amp; land</b><p>What cannot be said without a parcel.</p>Inspect gaps →</a><a href="schools.html"><b>Schools &amp; workforce</b><p>District scale, enrollment, missing measures.</p>Read the evidence →</a><a href="taxes.html"><b>Taxes &amp; transaction costs</b><p>Prop 13, transfer taxes, ULA, §1031, gains.</p>Model the net →</a><a href="decisions.html"><b>Decision pathways</b><p>Six routes, their triggers and their risks.</p>Compare routes →</a><a href="model.html"><b>Projection framework</b><p>Verified anchors, and the forecasts withheld.</p>See the limits →</a></div>'''

Path('index.html').write_text(shell('index','Executive summary',content))
src={'title':'Official source register','columns':['Publisher / document','Type','Reviewed','Use and limits'],'rows':[dict(cells=[s['label'],s['type'],s['checked'],'Primary source checked for published observations; not a property appraisal.'],status='Verified',source=k) for k,s in D['sources'].items()]}
content='''<div class="eyebrow">08 / AUDIT TRAIL</div><h1>Sources &amp; methodology</h1><p class="lede">Evidence first. Interpretation second. Unknowns stay unknown.</p><section class="callout"><h2>Verification standard</h2><p>Verified rows are source-matched observations re-read from the publisher page on 10 November 2026; the full row-by-row records are <code>research/VERIFICATION-2026-11-10-203ae19e.md</code> and <code>research/VERIFICATION-2026-11-10-882bff85.md</code> (prior: <code>research/VERIFICATION-2026-11-08.md</code>) in the repository. Department of Education district data for Los Angeles Unified was also read; no school attendance boundary can be assigned to an unidentified parcel. A link is not a guarantee that a rolling source will retain an earlier value. Verified means the source reports the observation—not that it predicts this property. Issuer reports are labeled separately from government data.</p><p>The break-even calculation on the projection page is arithmetic, not a forecast: <code>scripts/projection.py</code> derives it from the disclosed assumptions with no randomness and no network, and every output is a multiple of one year of contractual rent because no cap rate, rent or price for this asset can be verified.</p><p>Analysis rows are our conditional reasoning. Their official links support background context only; they do not endorse the recommendation. Unverified rows contain no invented value; links are research routes or explicitly limited context, not proof of missing facts.</p><p>QuickFacts observations use different vintages, geography and survey periods. ACS estimates have sampling error; no tract estimates or margins of error were obtained. The BLS November 4, 2026 summary uses unadjusted data and may be revised. Hazard context is drawn from USGS scenario modelling and CAL FIRE incident records, not from parcel-level analysis. No model has been trained or back-tested; no causal claim about property value is made.</p><h3>Privacy and publication boundary</h3><p>Asset A and Owner A are placeholders. No addresses, parcel IDs, owner names, contact details, financial accounts or private lease records are collected or published. No analytics, third-party embeds or external scripts are used. GitHub hosting may retain standard access logs. Public source links open their publishers’ websites.</p><h3>Reproducibility and maintenance</h3><p>Public evidence is stored in data/evidence.json; scripts/build.py generates every page. scripts/validate.py checks table provenance, local links and blank-value status. Source values were reviewed manually; automated validation does not assert live external availability or semantic verification. This is a fixed snapshot, not a live data feed. Refresh official releases and reassess geographic fit before acting.</p><p>Earlier companion reports, including the <code>/advisory/</code> layer and its numerical projections, are retained in the repository but excluded from this public site pending independent validation; see Flagged for Review. No hidden property records or private evidence were inferred. Missing private documents cannot be supplied through autonomous public research.</p></section>'''+table(src)
Path('sources.html').write_text(shell('sources','Sources & methodology',content))
